73	impl SemanticProp {
74	    fn structural_hash(&self) -> u64 {
75	        let mut hasher = FxHasher::default();
76	        self.name.hash(&mut hasher);
77	        self.required.hash(&mut hasher);
78	        self.react_declared.hash(&mut hasher);
79	        self.description.hash(&mut hasher);
80	        self.tags.hash(&mut hasher);
81	        for parent in self.parent.iter().chain(&self.declarations) {
82	            parent.name.hash(&mut hasher);
83	            parent.file_name.hash(&mut hasher);
84	        }
85	        self.prop_type.structural_hash(&mut hasher);
86	        hasher.finish()
87	    }
88	}
