90	/// Shares identical props between components, as the structural resolver does: a design system's components repeat
91	/// the same few hundred props, and Chakra's 600 components would otherwise hold 470,000 copies.
92	#[derive(Debug, Default)]
93	pub struct PropInterner {
94	    by_hash: Mutex<FxHashMap<u64, Vec<Arc<SemanticProp>>>>,
95	}
96	
97	impl PropInterner {
98	    /// The one shared copy of `prop`: an equal prop interned earlier, or `prop` itself the first time. If the internal
99	    /// lock is poisoned it returns `prop` unshared rather than failing.
100	    pub fn share(&self, prop: SemanticProp) -> Arc<SemanticProp> {
101	        self.share_arc(Arc::new(prop))
102	    }
103	
104	    /// [`Self::share`] for a prop already behind an `Arc`, such as one another interner shared: the one copy equal to
105	    /// it, or `prop` itself the first time.
106	    pub fn share_arc(&self, prop: Arc<SemanticProp>) -> Arc<SemanticProp> {
107	        let hash = prop.structural_hash();
108	        let Ok(mut by_hash) = self.by_hash.lock() else { return prop };
109	        let bucket = by_hash.entry(hash).or_default();
110	        if let Some(existing) = bucket.iter().find(|existing| ***existing == *prop) {
111	            return existing.clone();
112	        }
113	        bucket.push(prop.clone());
114	        prop
115	    }
116	}
