176	/// A checker that answers for components as they are asked about, for a long-lived session.
177	///
178	/// `request` never blocks: it queues the targets and returns the receiver that yields the outcome once the checker
179	/// has it, so a caller can wait a bounded time and take the structural answer when the checker is slower.
180	pub trait SemanticProvider: Send + Sync {
181	    /// Queues `targets` for the checker and returns at once with the receiver that will yield their
182	    /// [`SemanticOutcome`]. Someone is waiting for it: the request is [`Priority::Interactive`].
183	    fn request(&self, targets: Vec<SemanticTarget>) -> std::sync::mpsc::Receiver<SemanticOutcome>;
184	
185	    /// Queues `targets` at `priority` and returns at once; `delivery` receives the outcome. A checker that answers one
186	    /// request at a time answers an interactive request before a background one, and reads `priority` again when it
187	    /// picks the next, since a caller that joins a background request may raise it. The default ignores the priority
188	    /// and waits for [`Self::request`]'s receiver on a thread of its own.
189	    fn request_at(&self, targets: Vec<SemanticTarget>, priority: SharedPriority, delivery: Delivery) {
190	        drop(priority);
191	        let receiver = self.request(targets);
192	        let delivery = Arc::new(Mutex::new(Some(delivery)));
193	        let take =
194	            |slot: &Mutex<Option<Delivery>>| slot.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take();
195	        let waiter = delivery.clone();
196	        let waiting = std::thread::Builder::new().name("caliper-checker-answer".to_string()).spawn(move || {
197	            let outcome = receiver.recv().ok();
198	            if let Some(delivery) = take(&waiter) {
199	                delivery.deliver(outcome);
200	            }
201	        });
202	        if let Err(error) = waiting
203	            && let Some(delivery) = take(&delivery)
204	        {
205	            delivery.deliver(Some(SemanticOutcome::unavailable(format!(
206	                "could not start a thread to wait for it: {error}"
207	            ))));
208	        }
209	    }
210	
211	    /// Tells the checker that files changed on disk, before any request that may read them is queued. A checker that
212	    /// keeps what it read (a warm `tsc` holding a snapshot, ADR 0026) reads them again; one that reads every file
213	    /// afresh for each request needs nothing, which is the default.
214	    fn changed(&self, _change: SourceChange) {}
215	}
