217	/// Who waits for a request to the checker, which decides what a busy checker answers first.
218	#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
219	pub enum Priority {
220	    /// A component someone is looking at now: a story that was opened.
221	    Interactive,
222	    /// Work nobody waits for yet: a warm-up, a fill, a prefetch.
223	    Background,
224	}
