226	/// The priority of one queued request, shared between the caller and the checker so that a later caller can raise it
227	/// ([`SharedPriority::raise`]) while the request waits. Clones share one priority.
228	#[derive(Debug, Clone)]
229	pub struct SharedPriority(Arc<std::sync::atomic::AtomicBool>);
230	
231	impl SharedPriority {
232	    /// A priority that starts at `priority`.
233	    pub fn new(priority: Priority) -> Self {
234	        Self(Arc::new(std::sync::atomic::AtomicBool::new(priority == Priority::Interactive)))
235	    }
236	
237	    /// The priority now.
238	    pub fn get(&self) -> Priority {
239	        match self.0.load(std::sync::atomic::Ordering::Acquire) {
240	            true => Priority::Interactive,
241	            false => Priority::Background,
242	        }
243	    }
244	
245	    /// Makes the request interactive: someone is now waiting for it.
246	    pub fn raise(&self) {
247	        self.0.store(true, std::sync::atomic::Ordering::Release);
248	    }
249	}
