251	/// Where the outcome of a request made with [`SemanticProvider::request_at`] goes. It is used once: with the outcome,
252	/// or with `None` when the checker stopped without answering. Dropping it unused counts as `None`, so a caller is
253	/// told even when the request is lost (a worker that stopped, a thread that could not start).
254	pub struct Delivery(Option<Box<dyn FnOnce(Option<SemanticOutcome>) + Send>>);
255	
256	impl Delivery {
257	    /// A delivery that hands the outcome to `receive`.
258	    pub fn new(receive: impl FnOnce(Option<SemanticOutcome>) + Send + 'static) -> Self {
259	        Self(Some(Box::new(receive)))
260	    }
261	
262	    /// Hands over the outcome, or `None` for a checker that stopped without answering.
263	    pub fn deliver(mut self, outcome: Option<SemanticOutcome>) {
264	        if let Some(receive) = self.0.take() {
265	            receive(outcome);
266	        }
267	    }
268	}
269	
270	impl Drop for Delivery {
271	    fn drop(&mut self) {
272	        if let Some(receive) = self.0.take() {
273	            receive(None);
274	        }
275	    }
276	}
