278	impl std::fmt::Debug for Delivery {
279	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
280	        f.debug_struct("Delivery").field("delivered", &self.0.is_none()).finish()
281	    }
282	}
