309	/// Whether a merge may take a fact the checker does not supply from the structural resolver's answer for the same prop.
310	///
311	/// `Off` is the test-only mode of ADR 0026's S7 gates (`extract --no-resolver-facts`, which the construct suite's
312	/// checker lane runs): the merged facts come from the checker and oxc's syntax alone, as they will once the resolver is
313	/// deleted (S7e). S7a2 covers `defaultValue` and union member order; S7b extends it to the other facts.
314	#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
315	pub enum ResolverFacts {
316	    /// Where oxc's syntax does not tell, the structural answer does.
317	    #[default]
318	    Used,
319	    /// The structural answer is not read for these facts.
320	    Off,
321	}
