323	/// Replaces `entry`'s props and `composes` with the checker's, keeping a description or tags only the structural pass
324	/// has, for the whole-project merge. Facts are read as [`merge_semantic_props`] reads them, from `syntax` and as
325	/// `resolver` allows.
326	fn apply_props(
327	    entry: &mut ComponentEntry,
328	    semantic: &SemanticComponent,
329	    shared: &mut FxHashMap<u64, Vec<Arc<ParsedProp>>>,
330	    memo: &mut MergeMemo,
331	    syntax: &SourceSyntax,
332	    resolver: ResolverFacts,
333	) -> MergedProps {
334	    // The whole-project merge replaces the props and leaves `@types/react`'s to the inheritance layers.
335	    let own = semantic.props.iter().filter(|prop| !prop.react_declared);
336	    let merge = Merge { composes: semantic.composes.as_deref(), unanswered: Unanswered::Drop, syntax, resolver };
337	    replace_props(entry, own, &merge, shared, memo)
338	}
