362	/// How a merge went for one component.
363	#[derive(Debug, Clone, Default, PartialEq)]
364	pub struct MergedProps {
365	    /// Structural props the checker did not return, kept as the structural pass resolved them.
366	    pub kept: usize,
367	    /// Props the checker returned with a type it could not read (an `opaque` part: an import that does not resolve, a
368	    /// conditional type it left open), where the structural pass read the type in full. They keep the structural type,
369	    /// and their `degradedBy` also lists what the checker could not read.
370	    pub unread: usize,
371	    /// A source file the merge could not read for the defaults and union order of the answer.
372	    pub diagnostics: Vec<Diagnostic>,
373	}
