375	/// Merges the checker's `props` into `entry` by name: the checker's type, optionality, description, tags, `parent` and
376	/// `declarations` win where both have a prop, and every structural prop the checker did not return stays as the
377	/// structural pass resolved it. `composes` replaces the entry's when the checker decided it, and an undecided one leaves
378	/// the structural `composes` ([`SemanticComponent::composes`]). A prop whose checker
379	/// type holds an `opaque` part, where the structural type holds none, keeps the structural type and adds the checker's
380	/// reasons to its `degradedBy`: the checker's answer there is a placeholder, and the structural one is not confirmed,
381	/// so it is marked. A type the checker only cut at a limit (`truncated`) is still its answer.
382	///
383	/// Two facts the checker does not have come from oxc's syntax, read from the files the answer names: a prop's default
384	/// (the component's code: a destructured parameter's initializer, `defaultProps`; else the checker's `@default` tag)
385	/// and the order of a union's members (the order its declaration writes them in). The structural answer gives them
386	/// where the syntax does not tell ([`ResolverFacts::Used`]).
387	pub fn merge_semantic_props<'a>(
388	    entry: &mut ComponentEntry,
389	    props: impl Iterator<Item = &'a Arc<SemanticProp>>,
390	    composes: Option<&[String]>,
391	    shared: &mut FxHashMap<u64, Vec<Arc<ParsedProp>>>,
392	) -> MergedProps {
393	    let props: Vec<Arc<SemanticProp>> = props.cloned().collect();
394	    let syntax = SourceSyntax::read(std::iter::once((&*entry, props.as_slice())));
395	    let merge = Merge { composes, unanswered: Unanswered::Keep, syntax: &syntax, resolver: ResolverFacts::Used };
396	    let mut merged = replace_props(entry, props.iter(), &merge, shared, &mut MergeMemo::default());
397	    merged.diagnostics = syntax.diagnostics;
398	    merged
399	}
