401	/// The kinds of what the checker could not read in `checker`, when the structural type `structural` read everything:
402	/// then the structural type is kept and marked with them. Empty when the checker's type is its answer.
403	fn unread_by_checker(checker: &PropType, structural: &PropType) -> Vec<&'static str> {
404	    let unread: Vec<&'static str> = checker.degraded_by().into_iter().filter(|kind| *kind != TRUNCATED_KIND).collect();
405	    if unread.is_empty() || structural.degraded_by().iter().any(|kind| *kind != TRUNCATED_KIND) {
406	        return Vec::new();
407	    }
408	    unread
409	}
