411	/// The one diagnostic for the props of `affects` that kept their structural type because the checker could not read it
412	/// ([`MergedProps::unread`]); each such prop says why in its `degradedBy`.
413	pub(crate) fn unread_diagnostic(props: usize, affects: Vec<String>) -> Diagnostic {
414	    let mut diagnostic = Diagnostic::new(
415	        DiagnosticSeverity::Info,
416	        DiagnosticCode::SemanticBackend,
417	        format!(
418	            "{props} prop(s) of {} component(s) keep their structural type: the TypeScript checker could not read it, \
419	             and their degradedBy says what it could not read",
420	            affects.len()
421	        ),
422	    );
423	    diagnostic.affects = affects;
424	    diagnostic
425	}
