427	/// A component the checker answered for, as [`drop_superseded`] reads it.
428	pub(crate) struct Superseding<'a> {
429	    key: &'a str,
430	    /// A structural prop the checker did not return still holds a part the structural pass could not read, which a
431	    /// structural diagnostic naming the component may be about.
432	    structural_left: bool,
433	    /// A prop of the merged answer holds a name the checker could not resolve either.
434	    unresolved: bool,
435	}
436	
437	impl<'a> Superseding<'a> {
438	    /// `key`'s component as `merged` holds it after the checker's props were merged in. `structural_left` says whether a
439	    /// structural prop the checker did not return still holds a part the structural pass could not read.
440	    pub(crate) fn new(key: &'a str, merged: &ComponentEntry, structural_left: bool) -> Self {
441	        let unresolved_kind = OpaqueReason::UnresolvableImport { specifier: String::new() }.kind();
442	        let unresolved = merged.props.values().any(|prop| prop.degraded_by.iter().any(|kind| kind == unresolved_kind));
443	        Self { key, structural_left, unresolved }
444	    }
445	
446	    fn supersedes(&self, superseded: Superseded) -> bool {
447	        match superseded {
448	            Superseded::No => false,
449	            Superseded::Yes => !self.structural_left,
450	            Superseded::UnlessUnresolvedByChecker => !self.structural_left && !self.unresolved,
451	        }
452	    }
453	}
