455	/// Takes the components the checker answered for out of the `affects` of each structural diagnostic its answer
456	/// supersedes ([`DiagnosticCode::superseded_by_checker`]), and drops a diagnostic left affecting no component. A
457	/// diagnostic that affected none (a file's, the run's) is about no component's props and stays. Both merges call it
458	/// before the checker's own diagnostics join `diagnostics`, so it reads only the structural pass's.
459	pub(crate) fn drop_superseded(diagnostics: &mut Vec<Diagnostic>, answered: &[Superseding<'_>]) {
460	    if answered.is_empty() {
461	        return;
462	    }
463	    let by_key: FxHashMap<&str, &Superseding<'_>> = answered.iter().map(|answer| (answer.key, answer)).collect();
464	    diagnostics.retain_mut(|diagnostic| {
465	        if diagnostic.affects.is_empty() {
466	            return true;
467	        }
468	        let superseded = diagnostic.code.superseded_by_checker();
469	        diagnostic.affects.retain(|key| by_key.get(key.as_str()).is_none_or(|answer| !answer.supersedes(superseded)));
470	        !diagnostic.affects.is_empty()
471	    });
472	}
