474	/// What a merge does with a structural prop the checker did not return.
475	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
476	enum Unanswered {
477	    /// The checker decides which props exist, as in the whole-project merge: the structural prop is dropped.
478	    Drop,
479	    /// The checker's props are merged by name, as in a session's merge: the structural prop stays as resolved.
480	    Keep,
481	}
