483	/// How one merge reads what the checker does not answer.
484	struct Merge<'a> {
485	    composes: Option<&'a [String]>,
486	    unanswered: Unanswered,
487	    syntax: &'a SourceSyntax,
488	    resolver: ResolverFacts,
489	}
