491	/// A prop's default: the component's code default for it, else the checker's `@default` (or `@defaultValue`) tag, else
492	/// with [`ResolverFacts::Used`] the structural default. The code wins over the tag, as in react-docgen-typescript.
493	fn default_of(
494	    code: Option<&DefaultValue>,
495	    checker_tags: &BTreeMap<String, String>,
496	    structural: Option<&ParsedProp>,
497	    resolver: ResolverFacts,
498	) -> Option<DefaultValue> {
499	    if let Some(code) = code {
500	        return Some(code.clone());
501	    }
502	    let tag = checker_tags.get("default").or_else(|| checker_tags.get("defaultValue"));
503	    if let Some(tag) = tag {
504	        return Some(DefaultValue { value: tag.trim().to_owned(), computed: false });
505	    }
506	    match resolver {
507	        ResolverFacts::Used => structural.and_then(|structural| structural.default_value.clone()),
508	        ResolverFacts::Off => None,
509	    }
510	}
511	
512	/// The checker's type with its union members in declared order: the order the declaration writes them in where it
513	/// states every member, else the structural union's order where that placed any member (with
514	/// [`ResolverFacts::Used`]), else the written order of the members the declaration does state. Neither leaves the
515	/// checker's order. A structural order that placed members is kept even where it is the checker's own: the partial
516	/// written order would put the members it does not state last, where they may not have been written.
517	fn declared_order(
518	    checker: PropType,
519	    written: Option<&[WrittenMember]>,
520	    structural: Option<&ParsedProp>,
521	    resolver: ResolverFacts,
522	) -> PropType {
523	    let structural = match resolver {
524	        ResolverFacts::Used => structural,
525	        ResolverFacts::Off => None,
526	    };
527	    // The structural order also reaches the unions nested in members, which the written one does not.
528	    let (ordered, placed) = match structural {
529	        Some(structural) => {
530	            let placed = order::places_any(&checker, &structural.prop_type);
531	            (order::in_declared_order(checker, &structural.prop_type), placed)
532	        }
533	        None => (checker, false),
534	    };
535	    match written.and_then(|written| order::in_written_order(&ordered, written)) {
536	        Some((in_written, Placed::All)) => in_written,
537	        Some((in_written, Placed::Some)) if !placed => in_written,
538	        Some(_) | None => ordered,
539	    }
540	}
