542	fn replace_props<'a>(
543	    entry: &mut ComponentEntry,
544	    props_in: impl Iterator<Item = &'a Arc<SemanticProp>>,
545	    merge: &Merge<'_>,
546	    shared: &mut FxHashMap<u64, Vec<Arc<ParsedProp>>>,
547	    memo: &mut MergeMemo,
548	) -> MergedProps {
549	    let Merge { composes, unanswered, syntax, resolver } = *merge;
550	    let code_defaults = syntax.code_defaults(entry);
551	    let mut props: BTreeMap<String, Arc<ParsedProp>> = BTreeMap::new();
552	    let mut unread = 0;
553	    for prop in props_in {
554	        let structural = entry.props.get(&prop.name);
555	        let code_default = code_defaults.and_then(|defaults| defaults.get(&prop.name));
556	        // The union a prop with a `parent` writes is found by the prop alone, so it needs no place in the key; one with
557	        // none is looked for in the entry's own file.
558	        let written = prop.parent.is_none().then(|| syntax.written(entry, prop));
559	        let key: MergeKey = (
560	            Arc::as_ptr(prop) as usize,
561	            structural.map_or(0, |s| Arc::as_ptr(s) as usize),
562	            written.flatten().map_or((0, 0), |w| (w.as_ptr() as usize, w.len())),
563	            code_default.map_or(0, |d| std::ptr::from_ref(d) as usize),
564	        );
565	        if let Some(made) = memo.made.get(&key) {
566	            unread += usize::from(made.unread);
567	            props.insert(prop.name.clone(), made.merged.clone());
568	            continue;
569	        }
570	        let written = written.unwrap_or_else(|| syntax.written(entry, prop));
571	        let description = if prop.description.is_empty() {
572	            structural.map(|s| s.description.clone()).unwrap_or_default()
573	        } else {
574	            prop.description.clone()
575	        };
576	        let tags = if prop.tags.is_empty() {
577	            structural.map(|s| s.tags.clone()).unwrap_or_default()
578	        } else {
579	            prop.tags.clone()
580	        };
581	        let unread_kinds = structural.map(|s| unread_by_checker(&prop.prop_type, &s.prop_type)).unwrap_or_default();
582	        let prop_type = match structural {
583	            Some(structural) if !unread_kinds.is_empty() => structural.prop_type.clone(),
584	            Some(_) | None => declared_order(prop.prop_type.clone(), written, structural.map(|s| &**s), resolver),
585	        };
586	        unread += usize::from(!unread_kinds.is_empty());
587	        let merged = ParsedProp::new(
588	            prop.name.clone(),
589	            prop_type,
590	            prop.required,
591	            default_of(code_default, &prop.tags, structural.map(|s| &**s), resolver),
592	            description,
593	            tags,
594	            prop.parent.clone(),
595	            prop.declarations.clone(),
596	        )
597	        .degraded_also_by(&unread_kinds);
598	        let mut hasher = FxHasher::default();
599	        merged.structural_hash(&mut hasher);
600	        let bucket = shared.entry(hasher.finish()).or_default();
601	        let merged = match bucket.iter().find(|existing| ***existing == merged) {
602	            Some(existing) => existing.clone(),
603	            None => {
604	                let merged = Arc::new(merged);
605	                bucket.push(merged.clone());
606	                merged
607	            }
608	        };
609	        memo.made.insert(
610	            key,
611	            MemoEntry {
612	                _semantic: prop.clone(),
613	                _structural: structural.cloned(),
614	                merged: merged.clone(),
615	                unread: !unread_kinds.is_empty(),
616	            },
617	        );
618	        props.insert(prop.name.clone(), merged);
619	    }
620	    let mut kept = 0;
621	    if unanswered == Unanswered::Keep {
622	        for (name, structural) in &entry.props {
623	            if !props.contains_key(name) {
624	                props.insert(name.clone(), structural.clone());
625	                kept += 1;
626	            }
627	        }
628	    }
629	    entry.props = props;
630	    if let Some(composes) = composes {
631	        entry.composes = composes.to_vec();
632	    }
633	    MergedProps { kept, unread, diagnostics: Vec::new() }
634	}
635	
636	/// Merge the checker's props over `output`, component by component.
637	///
638	/// Per `docs/type-checker-integration.md`: the checker decides which props exist, their types, whether they are
639	/// required, `parent`, `declarations` and the component's `composes`; a description and tags come from the checker,
640	/// else the structural pass; a default value and a union's member order come from oxc's syntax, else the structural
641	/// pass ([`merge_semantic_props`]). Inheritance layers, curated inherited props and `discriminantProp` stay structural.
642	/// Components the checker did not answer for keep their structural result untouched. A structural diagnostic stops
643	/// naming a component the checker answered for when the answer supersedes it
644	/// ([`DiagnosticCode::superseded_by_checker`]), and goes once it names none.
645	///
646	/// Records provenance as `Info` diagnostics whose `affects` lists the output keys, so the canonical JSON gains no
647	/// field: one for the components the checker resolved, one per fallback reason.
648	pub fn merge_semantic(output: &mut ExtractionOutput, outcome: SemanticOutcome) {
649	    merge_semantic_with(output, outcome, ResolverFacts::Used);
650	}
651	
652	/// [`merge_semantic`], taking the facts the checker does not supply from the structural answer only as `resolver`
653	/// allows.
654	pub fn merge_semantic_with(output: &mut ExtractionOutput, outcome: SemanticOutcome, resolver: ResolverFacts) {
655	    let SemanticOutcome { components, fallbacks, diagnostics } = outcome;
656	    let syntax = SourceSyntax::read(
657	        components
658	            .iter()
659	            .filter_map(|semantic| Some((output.components.get(&semantic.key)?, semantic.props.as_slice()))),
660	    );
661	    let mut merged_keys = Vec::new();
662	    let (mut unread_keys, mut unread_props) = (Vec::new(), 0);
663	    let mut shared: FxHashMap<u64, Vec<Arc<ParsedProp>>> = FxHashMap::default();
664	    let mut memo = MergeMemo::default();
665	    for semantic in components {
666	        let Some(entry) = output.components.get_mut(&semantic.key) else { continue };
667	        let unread = apply_props(entry, &semantic, &mut shared, &mut memo, &syntax, resolver).unread;
668	        if unread > 0 {
669	            unread_props += unread;
670	            unread_keys.push(semantic.key.clone());
671	        }
672	        merged_keys.push(semantic.key);
673	    }
674	    // The whole-project merge drops every structural prop the checker did not return, so none is left over.
675	    let answered: Vec<Superseding<'_>> =
676	        merged_keys.iter().filter_map(|key| Some(Superseding::new(key, output.components.get(key)?, false))).collect();
677	    drop_superseded(&mut output.diagnostics, &answered);
678	    output.diagnostics.extend(diagnostics);
679	    output.diagnostics.extend(syntax.diagnostics);
680	
681	    if !merged_keys.is_empty() {
682	        merged_keys.sort();
683	        let mut provenance = Diagnostic::new(
684	            DiagnosticSeverity::Info,
685	            DiagnosticCode::SemanticBackend,
686	            format!("{} component(s) resolved by the TypeScript checker", merged_keys.len()),
687	        );
688	        provenance.affects = merged_keys;
689	        output.diagnostics.push(provenance);
690	    }
691	    if !unread_keys.is_empty() {
692	        unread_keys.sort();
693	        output.diagnostics.push(unread_diagnostic(unread_props, unread_keys));
694	    }
695	
696	    let mut by_reason: BTreeMap<String, Vec<String>> = BTreeMap::new();
697	    for SemanticFallback { key, reason } in fallbacks {
698	        if output.components.contains_key(&key) {
699	            by_reason.entry(reason).or_default().push(key);
700	        }
701	    }
702	    for (reason, mut keys) in by_reason {
703	        keys.sort();
704	        let mut diagnostic = Diagnostic::new(
705	            DiagnosticSeverity::Info,
706	            DiagnosticCode::SemanticBackend,
707	            format!("{} component(s) kept their structural result: {reason}", keys.len()),
708	        );
709	        diagnostic.affects = keys;
710	        output.diagnostics.push(diagnostic);
711	    }
712	}
