1	//! The canonical JSON of an [`ExtractionOutput`] (ADR 0009, ADR 0018): each distinct prop is written once, in a
2	//! top-level `props` table. A component's `props` lists the ids of prop sets, each a table entry that maps the names of
3	//! the props one declaring type contributes to prop ids; its inheritance layers' `omitted` lists are ids into a
4	//! `nameLists` table; its `notableInherited` maps names to prop ids. The Rust types keep all of it inline.
5	
6	use std::collections::BTreeMap;
7	use std::fmt;
8	use std::sync::Arc;
9	
10	use rayon::prelude::*;
11	use rustc_hash::FxHashMap;
12	use serde::ser::SerializeStruct;
13	use serde::{Serialize, Serializer};
14	
15	use super::{ComponentEntry, ExtractionOutput, InheritedLayer, ParsedProp};
16	use crate::types::Diagnostic;
17	
18	/// A prop's id in the table: the 64-bit FNV-1a hash of its compact JSON, written as 16 hex digits.
19	#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
20	pub(crate) struct PropId(u64);
21	
22	/// The id of a prop set in the `propSets` table: the hash of its (name, prop id) entries, in name order.
23	type SetId = PropId;
24	
25	/// The id of a list in the `nameLists` table: the hash of its names, in order.
26	type ListId = PropId;
27	
28	/// The (prop name, prop id) entries of one prop set, in name order.
29	type Members<'a> = Vec<(&'a str, PropId)>;
30	
31	const FNV_OFFSET: u64 = 0xcbf2_9ce4_8422_2325;
32	
33	fn fnv(hash: u64, bytes: &[u8]) -> u64 {
34	    bytes.iter().fold(hash, |hash, byte| (hash ^ u64::from(*byte)).wrapping_mul(0x0000_0100_0000_01b3))
35	}
36	
37	impl PropId {
38	    fn of(json: &[u8]) -> PropId {
39	        PropId(fnv(FNV_OFFSET, json))
40	    }
41	
42	    /// Names and ids are separated by bytes no JSON string holds unescaped, so `[("a", x)]` never hashes as another set.
43	    fn of_set(entries: &[(&str, PropId)]) -> SetId {
44	        PropId(
45	            entries.iter().fold(FNV_OFFSET, |hash, (name, id)| {
46	                fnv(fnv(fnv(hash, name.as_bytes()), &[0xff]), &id.0.to_le_bytes())
47	            }),
48	        )
49	    }
50	
51	    fn of_list(names: &[String]) -> ListId {
52	        PropId(names.iter().fold(FNV_OFFSET, |hash, name| fnv(fnv(hash, name.as_bytes()), &[0xff])))
53	    }
54	}
55	
56	impl fmt::Display for PropId {
57	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
58	        write!(f, "{:016x}", self.0)
59	    }
60	}
61	
62	impl Serialize for PropId {
63	    fn serialize<S: Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
64	        serializer.collect_str(self)
65	    }
66	}
