68	/// What a component's JSON refers to by id: its prop sets, its notable inherited props by name, and one omitted-names
69	/// list per inheritance layer, in layer order, with a members list for each layer that has members.
70	pub(crate) struct ComponentIds<'a> {
71	    props: Vec<SetId>,
72	    notable_inherited: Vec<(&'a str, PropId)>,
73	    omitted: Vec<ListId>,
74	    members: Vec<Option<ListId>>,
75	}
76	
77	/// The tables a set of components refer to: their distinct props, prop sets and omitted-names lists.
78	pub(crate) struct Tables<'a> {
79	    props: PropTable<'a>,
80	    prop_sets: BTreeMap<SetId, Members<'a>>,
81	    name_lists: NameLists<'a>,
82	}
83	
84	impl<'a> Tables<'a> {
85	    /// Write `props`, `propSets` and `nameLists` as the next fields of `out`.
86	    pub(crate) fn write<T: SerializeStruct>(&self, out: &mut T) -> Result<(), T::Error> {
87	        out.serialize_field("props", &self.props)?;
88	        out.serialize_field("propSets", &SetTable(&self.prop_sets))?;
89	        out.serialize_field("nameLists", &self.name_lists)
90	    }
91	
92	    /// Add the lists `diagnostics` name in `affects` to the `nameLists` table, and identify them.
93	    pub(crate) fn intern_affects<E: serde::ser::Error>(
94	        &mut self,
95	        diagnostics: &'a [Diagnostic],
96	    ) -> Result<InternedDiagnostics<'a>, E> {
97	        InternedDiagnostics::new(&mut self.name_lists, diagnostics)
98	    }
99	
100	    /// How many fields [`Tables::write`] adds to a struct.
101	    pub(crate) const FIELDS: usize = 3;
102	}
103	
104	/// The omitted or affected names the JSON refers to by id, each list written once.
105	pub(crate) type NameLists<'a> = BTreeMap<ListId, &'a [String]>;
106	
107	/// Add `names` to `lists` and return its id. Fails if a different list already holds the id.
108	fn add_list<'a, E: serde::ser::Error>(lists: &mut NameLists<'a>, names: &'a [String]) -> Result<ListId, E> {
109	    insert_list(lists, PropId::of_list(names), names)
110	}
111	
112	/// Add `names` under `id`, which is `PropId::of_list(names)`. Fails if a different list already holds the id.
113	fn insert_list<'a, E: serde::ser::Error>(
114	    lists: &mut NameLists<'a>,
115	    id: ListId,
116	    names: &'a [String],
117	) -> Result<ListId, E> {
118	    match lists.get(&id) {
119	        Some(existing) if *existing != names => {
120	            Err(E::custom(format!("two different name lists have the same id {id}: {existing:?} and {names:?}")))
121	        }
122	        Some(_) => Ok(id),
123	        None => {
124	            lists.insert(id, names);
125	            Ok(id)
126	        }
127	    }
128	}
129	
130	/// Diagnostics as the canonical JSON writes them: every field as `Diagnostic` derives, except that `affects` is the id
131	/// of a list in the `nameLists` table, and absent when the list is empty.
132	pub(crate) struct InternedDiagnostics<'a> {
133	    diagnostics: &'a [Diagnostic],
134	    affects: Vec<Option<ListId>>,
135	}
136	
137	impl<'a> InternedDiagnostics<'a> {
138	    /// Identify `diagnostics`' `affects` lists, adding them to `lists`.
139	    pub(crate) fn new<E: serde::ser::Error>(
140	        lists: &mut NameLists<'a>,
141	        diagnostics: &'a [Diagnostic],
142	    ) -> Result<Self, E> {
143	        // Hashing every name of every list is most of the work and is pure, so the ids come from all threads; the
144	        // table is filled, and a collision looked for, in diagnostic order as before.
145	        let ids: Vec<Option<ListId>> = diagnostics
146	            .par_iter()
147	            .with_min_len(16)
148	            .map(|diagnostic| (!diagnostic.affects.is_empty()).then(|| PropId::of_list(&diagnostic.affects)))
149	            .collect();
150	        let affects = diagnostics
151	            .iter()
152	            .zip(ids)
153	            .map(|(diagnostic, id)| id.map(|id| insert_list(lists, id, &diagnostic.affects)).transpose())
154	            .collect::<Result<_, E>>()?;
155	        Ok(InternedDiagnostics { diagnostics, affects })
156	    }
157	}
158	
159	struct InternedDiagnostic<'a> {
160	    diagnostic: &'a Diagnostic,
161	    affects: Option<ListId>,
162	}
163	
164	impl Serialize for InternedDiagnostic<'_> {
165	    fn serialize<S: Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
166	        // Destructured so a new field fails to compile here instead of going missing from the JSON.
167	        let Diagnostic { severity, message, file, line, column, help, code, affects: _ } = self.diagnostic;
168	        let mut out = serializer.serialize_struct("Diagnostic", 7 + usize::from(self.affects.is_some()))?;
169	        out.serialize_field("severity", severity)?;
170	        out.serialize_field("message", message)?;
171	        out.serialize_field("file", file)?;
172	        out.serialize_field("line", line)?;
173	        out.serialize_field("column", column)?;
174	        out.serialize_field("help", help)?;
175	        out.serialize_field("code", code)?;
176	        if let Some(affects) = &self.affects {
177	            out.serialize_field("affects", affects)?;
178	        }
179	        out.end()
180	    }
181	}
182	
183	impl Serialize for InternedDiagnostics<'_> {
184	    fn serialize<S: Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
185	        serializer.collect_seq(
186	            self.diagnostics
187	                .iter()
188	                .zip(&self.affects)
189	                .map(|(diagnostic, &affects)| InternedDiagnostic { diagnostic, affects }),
190	        )
191	    }
192	}
193	
194	struct SetTable<'a>(&'a BTreeMap<SetId, Vec<(&'a str, PropId)>>);
195	
196	impl Serialize for SetTable<'_> {
197	    fn serialize<S: Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
198	        serializer.collect_map(self.0.iter().map(|(id, entries)| (id, IdMap(entries))))
199	    }
200	}
201	
202	/// The distinct props of a set of components, each with the JSON its id was computed from.
203	pub(crate) struct PropTable<'a> {
204	    entries: BTreeMap<PropId, (&'a ParsedProp, Vec<u8>)>,
205	}
206	
207	impl Serialize for PropTable<'_> {
208	    fn serialize<S: Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
209	        serializer.collect_map(self.entries.iter().map(|(id, (prop, _))| (id, prop)))
210	    }
211	}
