213	/// Identify every prop of `entries`, collect the distinct ones, and group each component's props into prop sets by the
214	/// type that declares them. Components that inherit one interface share its props, so each shared allocation is
215	/// serialized once, and share its prop set, so the set is written once.
216	pub(crate) fn intern<'a, E: serde::ser::Error>(
217	    entries: &[&'a ComponentEntry],
218	) -> Result<(Vec<ComponentIds<'a>>, Tables<'a>), E> {
219	    let mut slots: FxHashMap<*const ParsedProp, usize> = FxHashMap::default();
220	    let mut allocations: Vec<&'a ParsedProp> = Vec::new();
221	    let mut slots_of = |props: &'a BTreeMap<String, Arc<ParsedProp>>| -> Vec<(&'a str, usize)> {
222	        props
223	            .iter()
224	            .map(|(name, prop)| {
225	                let slot = *slots.entry(Arc::as_ptr(prop)).or_insert_with(|| {
226	                    allocations.push(prop);
227	                    allocations.len() - 1
228	                });
229	                (name.as_str(), slot)
230	            })
231	            .collect()
232	    };
233	    let named: Vec<_> =
234	        entries.iter().map(|entry| (slots_of(&entry.props), slots_of(&entry.notable_inherited))).collect();
235	
236	    let identified: Vec<(PropId, Vec<u8>)> = allocations
237	        .par_iter()
238	        .map(|prop| {
239	            let json = serde_json::to_vec(prop)?;
240	            Ok((PropId::of(&json), json))
241	        })
242	        .collect::<serde_json::Result<_>>()
243	        .map_err(E::custom)?;
244	
245	    let mut table = PropTable { entries: BTreeMap::new() };
246	    let mut ids = Vec::with_capacity(identified.len());
247	    for (prop, (id, json)) in allocations.iter().copied().zip(identified) {
248	        table.add(prop, id, json)?;
249	        ids.push(id);
250	    }
251	
252	    let grouped: Vec<Vec<(SetId, Members<'a>)>> =
253	        named.par_iter().map(|(props, _)| group_into_sets(props, &allocations, &ids)).collect();
254	
255	    let mut prop_sets: BTreeMap<SetId, Members<'a>> = BTreeMap::new();
256	    let mut name_lists = NameLists::new();
257	    let mut components = Vec::with_capacity(entries.len());
258	    for ((entry, groups), (_, notable)) in entries.iter().zip(grouped).zip(named) {
259	        let mut set_ids = Vec::with_capacity(groups.len());
260	        for (id, members) in groups {
261	            match prop_sets.get(&id) {
262	                Some(existing) if *existing != members => {
263	                    return Err(E::custom(format!(
264	                        "two different prop sets have the same id {id}: {existing:?} and {members:?}"
265	                    )));
266	                }
267	                Some(_) => {}
268	                None => {
269	                    prop_sets.insert(id, members);
270	                }
271	            }
272	            set_ids.push(id);
273	        }
274	        let omitted = entry
275	            .inheritance
276	            .iter()
277	            .map(|layer| add_list(&mut name_lists, &layer.omitted))
278	            .collect::<Result<Vec<_>, E>>()?;
279	        let members =
280	            entry
281	                .inheritance
282	                .iter()
283	                .map(|layer| {
284	                    if layer.members.is_empty() {
285	                        Ok(None)
286	                    } else {
287	                        add_list(&mut name_lists, &layer.members).map(Some)
288	                    }
289	                })
290	                .collect::<Result<Vec<_>, E>>()?;
291	        let by_name = |slots: Vec<(&'a str, usize)>| -> Vec<(&'a str, PropId)> {
292	            slots.into_iter().map(|(name, slot)| (name, ids[slot])).collect()
293	        };
294	        components.push(ComponentIds { props: set_ids, notable_inherited: by_name(notable), omitted, members });
295	    }
296	    Ok((components, Tables { props: table, prop_sets, name_lists }))
297	}
298	
299	/// Split a component's props by the type that declares them, and identify each group. The declaring type is the unit
300	/// components share, so a group that two components inherit is the same set in both. A prop with no declaring type
301	/// forms a group of its own, first.
302	fn group_into_sets<'a>(
303	    props: &[(&'a str, usize)],
304	    allocations: &[&ParsedProp],
305	    ids: &[PropId],
306	) -> Vec<(SetId, Members<'a>)> {
307	    let mut groups: BTreeMap<Option<(&str, &str)>, Members<'a>> = BTreeMap::new();
308	    for &(name, slot) in props {
309	        let parent = allocations[slot].parent.as_ref().map(|parent| (parent.name.as_str(), parent.file_name.as_str()));
310	        groups.entry(parent).or_default().push((name, ids[slot]));
311	    }
312	    groups.into_values().map(|members| (PropId::of_set(&members), members)).collect()
313	}
314	
315	impl<'a> PropTable<'a> {
316	    /// Add `prop` under `id`, the hash of `json`. Fails if a different prop already holds the id, so one can never stand
317	    /// in for the other.
318	    fn add<E: serde::ser::Error>(&mut self, prop: &'a ParsedProp, id: PropId, json: Vec<u8>) -> Result<(), E> {
319	        match self.entries.get(&id) {
320	            Some((_, existing)) if *existing != json => Err(E::custom(format!(
321	                "prop '{}' and a different prop have the same id {id}: {} and {}",
322	                prop.name,
323	                String::from_utf8_lossy(existing),
324	                String::from_utf8_lossy(&json)
325	            ))),
326	            Some(_) => Ok(()),
327	            None => {
328	                self.entries.insert(id, (prop, json));
329	                Ok(())
330	            }
331	        }
332	    }
333	}
