335	/// A component as the canonical JSON writes it: every field as `ComponentEntry` derives it, except that `props` and
336	/// `notableInherited` hold ids.
337	pub(crate) struct InternedComponent<'a> {
338	    pub(crate) entry: &'a ComponentEntry,
339	    pub(crate) ids: &'a ComponentIds<'a>,
340	}
