394	    fn serialize<S: Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
395	        // Destructured so a new field fails to compile here instead of going missing from the JSON.
396	        let ComponentEntry {
397	            display_name,
398	            file_path,
399	            description,
400	            props: _,
401	            inheritance,
402	            notable_inherited: _,
403	            discriminant_prop,
404	            composes,
405	            tags,
406	            methods,
407	            detected_by,
408	            exported,
409	            exports,
410	        } = self.entry;
411	        let mut out = serializer.serialize_struct("ComponentEntry", 13)?;
412	        out.serialize_field("displayName", display_name)?;
413	        out.serialize_field("filePath", file_path)?;
414	        out.serialize_field("description", description)?;
415	        out.serialize_field("props", &self.ids.props)?;
416	        out.serialize_field(
417	            "inheritance",
418	            &InternedLayers { layers: inheritance, omitted: &self.ids.omitted, members: &self.ids.members },
419	        )?;
420	        out.serialize_field("notableInherited", &IdMap(&self.ids.notable_inherited))?;
421	        out.serialize_field("discriminantProp", discriminant_prop)?;
422	        out.serialize_field("composes", composes)?;
423	        out.serialize_field("tags", tags)?;
424	        out.serialize_field("methods", methods)?;
425	        out.serialize_field("detectedBy", detected_by)?;
